async def long_task():
    try:
        print("Start")
        await asyncio.sleep(10)
        print("End")
    except asyncio.CancelledError:
        print("Cleanup")

async def main():
    try:
        await asyncio.wait_for(long_task(), timeout=1.0)
    except asyncio.TimeoutError:
        print("Timeout")

